import 'package:cloud_firestore/cloud_firestore.dart';
class CheckInService{final FirebaseFirestore db;CheckInService({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance;Future<void> save(String u,int mood,String note)async{await db.collection('users').doc(u).collection('check_ins').doc(DateTime.now().toUtc().toIso8601String().substring(0,10)).set({'mood':mood,'note':note.trim(),'createdAt':FieldValue.serverTimestamp()});}Stream<QuerySnapshot<Map<String,dynamic>>> watch(String u)=>db.collection('users').doc(u).collection('check_ins').orderBy('createdAt',descending:true).limit(30).snapshots();}